const statusData = $('2. Get Server Status').first().json.response || {};
const dbData = $('3. Get Hosted Databases').first().json.response || { databases: [] };
const clientsData = $('4. Get Connected Users').first().json.response || { clients: [] };
const sshOutputStr = $('5. Get OS Metrics (SSH)').first().json.stdout || '{}';

let sshData = {};
try { sshData = JSON.parse(sshOutputStr); } catch (err) { }

let elapsedCall = 0;
let cacheHit = 0;
let unsavedCache = 0;
let remoteCalls = 0;
let ioTime = 0;
let netIn = 0;
let netOut = 0;

if (sshData.statsLine) {
   let statsStr = typeof sshData.statsLine === 'string' ? sshData.statsLine : (sshData.statsLine.value || '');
   const parts = statsStr.split('\t');
   if (parts.length >= 12) {
      netIn = parseFloat(parts[1]) / 1024;
      netOut = parseFloat(parts[2]) / 1024;
      unsavedCache = parseFloat(parts[5]);
      cacheHit = parseFloat(parts[6]);
      remoteCalls = parseInt(parts[8], 10);
      elapsedCall = parseFloat(parts[9]);
      ioTime = parseFloat(parts[11]);
   }
}

const filesFormatted = (dbData.databases || dbData.files || []).map(f => ({
  name: f.filename || f.name,
  size: f.size ? `${(f.size / 1073741824).toFixed(2)} GB` : 'N/A',
  clients: f.clientsCount || f.clients || 0,
  status: f.status || 'NORMAL'
}));

const usersFormatted = (clientsData.clients || []).map(c => {
  let accountName = 'N/A';
  let database = 'N/A';
  let privsetName = '';
  let allDatabases = [];
  if (c.guestFiles && c.guestFiles.length > 0) {
    accountName = c.guestFiles[0].accountName || accountName;
    database = c.guestFiles[0].filename || database;
    privsetName = c.guestFiles[0].privsetName || '';
    allDatabases = [...new Set(c.guestFiles.map(g => g.filename).filter(Boolean))];
  }
  return {
    sessionIdentifier: c.userName || c.id,
    accountName: accountName,
    privsetName: privsetName,
    ipAddress: c.ipaddress || c.computerName || '',
    computerName: c.computerName || '',
    connectTime: c.connectTime || '',
    connectDuration: c.connectDuration || '',
    clientType: c.appType || c.clientType || 'Unknown',
    appVersion: c.appVersion || '',
    operatingSystem: c.operatingSystem || '',
    database: database,
    allDatabases: allDatabases
  };
});

const hasSpike = elapsedCall > 20;
let latencySource = "Operating within normal SLA parameters.";
if (hasSpike && sshData.topLine) {
    let topStr = typeof sshData.topLine === 'string' ? sshData.topLine : (sshData.topLine.value || '');
    if (!topStr.includes('cannot find')) {
        const parts = topStr.split('\t');
        if (parts.length >= 6) {
            latencySource = `Slow operation detected: ${parts[4] || 'Heavy Operation'} on ${parts[5] || 'Unknown Table'}.`;
        }
    }
}

const allClientsList = clientsData.clients || [];
const payload = {
  serverHost: 'https://demo.master-bom.com',
  environment: 'Demo',
  timestamp: new Date().toISOString(),
  metrics: {
    elapsed: elapsedCall || 0,
    elapsedThreshold: 20.0,
    cacheHit: cacheHit || 100,
    unsavedCache: unsavedCache || 0,
    remoteCalls: remoteCalls || 0,
    ioTime: ioTime || 0,
    sessions: allClientsList.length,
    sessionsMax: parseInt(statusData.maxConnections || 100, 10),
    cpu: parseFloat(sshData.cpu || 0).toFixed(1),
    ramUsed: parseFloat(sshData.memUsed || 0).toFixed(1),
    ramTotal: parseFloat(sshData.memTotal || 64.0).toFixed(1),
    diskUsed: parseFloat(sshData.diskUsed || 0).toFixed(1),
    diskTotal: parseFloat(sshData.diskTotal || 0).toFixed(1),
    netIn: parseFloat(netIn || 0).toFixed(1),
    netOut: parseFloat(netOut || 0).toFixed(1),
    breakdown: {
      pro: allClientsList.filter(c => (c.appType || c.clientType || '').toLowerCase().includes('pro')).length,
      web: allClientsList.filter(c => (c.appType || c.clientType || '').toLowerCase().includes('web')).length,
      go: allClientsList.filter(c => (c.appType || c.clientType || '').toLowerCase().includes('go')).length,
      api: allClientsList.filter(c => (c.appType || c.clientType || '').toLowerCase().includes('api') || (c.appType || c.clientType || '').toLowerCase().includes('dapi')).length,
      fmse: allClientsList.filter(c => (c.appType || c.clientType || '').toLowerCase().includes('fmse') || (c.appType || c.clientType || '').toLowerCase().includes('sase') || (c.computerName || '').toLowerCase().includes('script')).length
    }
  },
  alert: {
    active: hasSpike,
    title: hasSpike ? `LATENCY SPIKE DETECTED: ${elapsedCall} ms / Call` : 'ALL CLEAR',
    desc: latencySource
  },
  databases: filesFormatted,
  connectedUsers: usersFormatted
};

return [{ json: payload }];
